input.command:
cd /tmp/cs && t(){ printf "%-28s " "$1"; /workspace/executable -c "$2" -o q.png --silent --config c2.json --scale-factor 8 2>/dev/null; python3 /tmp/cs/dim.py q.png; }
for k in 0 1 2 3 4 5 6 7 8; do t "x*60 then tab at $k" "$(python3 -c "print('x'*$k+'\t'+'x'*(60-$k))")"; done
t "60x+2sp" "$(python3 -c "print('x'*60+'  ')")"

cd /tmp/cs && cat > sample.py <<'PY'
import sys; sys.path.insert(0,'/tmp/cs')
from png import *
from collections import Counter
w,h,bpp,rows=readpng(sys.argv[1])
c=Counter()
for y in range(h):
    for x in range(w):
        c[px(rows,bpp,x,y)[:3]]+=1
for col,n in c.most_common(40):
    print('#%02x%02x%02x'%col, n)
PY
python3 sample.py d1.png

cd /tmp/cs && /workspace/executable -c "$(printf 'aaa\nbbb\nccc')" -o hl.png --silent --config c2.json --scale-factor 1 --highlight-range 2:2 --highlight-range-color '#ff0000ff' && python3 -c "
import sys; sys.path.insert(0,'/tmp/cs')
from png import *
w,h,bpp,rows=readpng('/tmp/cs/hl.png')
print(w,h)
for y in range(h):
    r=[x for x in range(w) if px(rows,bpp,x,y)[:3]==(255,0,0)]
    if r: print('y',y,'x',min(r),max(r),len(r))
"

cd /tmp/cs && /workspace/executable -c '████' -o bk.png --silent --config c2.json --scale-factor 1 && python3 -c "
import sys; sys.path.insert(0,'/tmp/cs')
from png import *
w,h,bpp,rows=readpng('/tmp/cs/bk.png')
print(w,h)
for y in range(h):
