    if xs: print('y',y,'xmin',min(xs),'xmax',max(xs),'n',len(xs))
"

cd /tmp/cs && python3 mk2.py '{"snapshot_config":{"background":"#000000","watermark":null,"window":{"margin":{"x":0,"y":0},"shadow":{"radius":0,"color":"#00000000"},"radius":0,"border":{"width":0,"color":"#00000000"},"mac_window_bar":false}}}'
C=$(printf 'aaa\nbbb\nccc\nddd')
r(){ printf "%-34s " "$1"; shift; timeout 60 /workspace/executable -c "$C" -o q.png --config c2.json --scale-factor 1 --silent "$@" 2>&1|head -2; python3 -c "
import sys; sys.path.insert(0,'/tmp/cs')
from png import *
w,h,bpp,rows=readpng('/tmp/cs/q.png')
