for y in range(h):
    p=px(rows,bpp,300,y)[:3]
    seen.setdefault(p,[]).append(y)
for k,v in seen.items():
    if k!=(40,42,54): print('   ',k,v[0],v[-1])
"; }
r "delete 2" -d 2
